export const RATES = {
  handlingPerCarton: 0.15,
  handlingMinimum: 550,
  storagePerCuft: 0.18,
  monthlyStorageMinCuft: 65000,
  monthlyStorageMinRate: 0.24,
  monthlyStorageMinTotal: 15600,
  drayageRevenue: 495,
  chassisRevenuePerDay: 40,
  shrinkWrapPerPallet: 2.50,
  maDrayageCost: 425,
  maChassisCostPerDay: 30,
  fernandoBaseRate: 260,
  palletCost: 4.50,
};

export interface Container {
  id: string;
  container: string;
  status: "pending" | "in-transit" | "received" | "unloaded" | "billed" | "canceled" | "projected";
  eta: string;
  period: string;
  po: string;
  cartons: number;
  skuCount: number;
  pallets: number;
  billableCuft: number;
  billed: boolean;
  billingPeriod: string;

  // Inbound tracking
  inExtensiv: boolean;
  plReceived: boolean;
  doReceived: boolean;

  // Revenue
  handlingRevenue: number;
  storageRevenue: number;
  drayageRevenue: number;
  chassisRevenue: number;
  shrinkWrapRevenue: number;
  totalRevenue: number;

  // Costs
  fernandoRate: number;
  fernandoTotal: number;
  fernandoUnloadDate: string;
  maDrayageCost: number;
  maChassisCost: number;
  maChassisDays: number;
  maPickup: string;
  maReturn: string;
  palletCost: number;
  totalCost: number;

  // Margin
  grossMargin: number;

  // Notes
  notes: string;
  carrier: string;
}

function calcBilling(c: Partial<Container>): Partial<Container> {
  const cartons = c.cartons || 0;
  const pallets = c.pallets || Math.ceil(cartons / 60);
  const billableCuft = c.billableCuft || Math.max(pallets * 1.3 * 48, 0);

  const handlingRevenue = Math.max(cartons * RATES.handlingPerCarton, cartons > 0 ? RATES.handlingMinimum : 0);
  const storageRevenue = +(billableCuft * RATES.storagePerCuft).toFixed(2);
  const drayageRevenue = cartons > 0 ? RATES.drayageRevenue : 0;
  const chassisDays = c.maChassisDays || 0;
  const chassisRevenue = chassisDays * RATES.chassisRevenuePerDay;
  const shrinkWrapRevenue = +(pallets * RATES.shrinkWrapPerPallet).toFixed(2);
  const totalRevenue = +(handlingRevenue + storageRevenue + drayageRevenue + chassisRevenue + shrinkWrapRevenue).toFixed(2);

  const fernandoRate = c.fernandoRate || RATES.fernandoBaseRate;
  const fernandoTotal = c.fernandoTotal || fernandoRate;
  const maDrayageCost = cartons > 0 ? RATES.maDrayageCost : 0;
  const maChassisCost = chassisDays * RATES.maChassisCostPerDay;
  const palletCostVal = +(pallets * RATES.palletCost).toFixed(2);
  const totalCost = +(fernandoTotal + maDrayageCost + maChassisCost + palletCostVal).toFixed(2);

  return {
    ...c,
    pallets,
    billableCuft: +billableCuft.toFixed(2),
    handlingRevenue: +handlingRevenue.toFixed(2),
    storageRevenue,
    drayageRevenue,
    chassisRevenue,
    shrinkWrapRevenue,
    totalRevenue,
    fernandoRate,
    fernandoTotal,
    maDrayageCost,
    maChassisCost,
    maChassisDays: chassisDays,
    palletCost: palletCostVal,
    totalCost,
    grossMargin: +(totalRevenue - totalCost).toFixed(2),
  };
}

export { calcBilling };

